import React from 'react';
import { motion } from 'framer-motion';
import { 
  IconTrophy,
  IconTimer,
  IconStatistics,
  IconFire
} from '../assets/icons';

const ProgressCard = ({ title, value, icon: Icon, color }) => (
  <motion.div
    whileHover={{ scale: 1.02 }}
    className="bg-gray-800/50 p-6 rounded-2xl backdrop-blur-xl border border-white/10 shadow-xl"
  >
    <div className="flex items-center gap-4">
      <div className={`w-12 h-12 rounded-xl ${color} flex items-center justify-center`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
      <div>
        <h3 className="text-lg font-semibold text-white">{value}</h3>
        <p className="text-gray-400 text-sm">{title}</p>
      </div>
    </div>
  </motion.div>
);

const AchievementCard = ({ title, progress, icon: Icon, color }) => (
  <motion.div
    whileHover={{ scale: 1.02 }}
    className="bg-gray-800/50 p-6 rounded-2xl backdrop-blur-xl border border-white/10 shadow-xl"
  >
    <div className="flex items-center gap-4 mb-4">
      <div className={`w-12 h-12 rounded-xl ${color} flex items-center justify-center`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
      <div className="flex-1">
        <h3 className="text-lg font-semibold text-white">{title}</h3>
        <div className="flex items-center gap-2">
          <div className="flex-1 h-2 bg-gray-700 rounded-full overflow-hidden">
            <motion.div
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{ duration: 1, ease: "easeOut" }}
              className={`h-full ${color}`}
            />
          </div>
          <span className="text-sm text-gray-400">{progress}%</span>
        </div>
      </div>
    </div>
  </motion.div>
);

const Progress = () => {
  const stats = [
    {
      title: "Study Hours",
      value: "120h",
      icon: IconTimer,
      color: "bg-blue-500"
    },
    {
      title: "Tasks Completed",
      value: "48",
      icon: IconTrophy,
      color: "bg-purple-500"
    },
    {
      title: "Focus Score",
      value: "92%",
      icon: IconStatistics,
      color: "bg-green-500"
    },
    {
      title: "Achievements",
      value: "15",
      icon: IconFire,
      color: "bg-orange-500"
    }
  ];

  const achievements = [
    {
      title: "Study Streak",
      progress: 80,
      icon: IconTimer,
      color: "bg-blue-500"
    },
    {
      title: "Focus Master",
      progress: 65,
      icon: IconFire,
      color: "bg-orange-500"
    },
    {
      title: "Knowledge Seeker",
      progress: 90,
      icon: IconStatistics,
      color: "bg-green-500"
    },
    {
      title: "Task Champion",
      progress: 75,
      icon: IconTrophy,
      color: "bg-purple-500"
    }
  ];

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="min-h-screen bg-gradient-to-b from-gray-900 to-gray-800 text-white p-6"
    >
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="text-center mb-10"
        >
          <h1 className="text-4xl font-bold mb-4 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
            Your Progress
          </h1>
          <p className="text-gray-300">
            Track your achievements and study progress
          </p>
        </motion.div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
          {stats.map((stat, index) => (
            <motion.div
              key={stat.title}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <ProgressCard {...stat} />
            </motion.div>
          ))}
        </div>

        {/* Achievements */}
        <motion.h2
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="text-2xl font-semibold mb-6"
        >
          Current Achievements
        </motion.h2>

        <div className="grid grid-cols-1 gap-6">
          {achievements.map((achievement, index) => (
            <motion.div
              key={achievement.title}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.5 + index * 0.1 }}
            >
              <AchievementCard {...achievement} />
            </motion.div>
          ))}
        </div>
      </div>
    </motion.div>
  );
};

export default Progress; 